import { toast } from 'react-toastify';
import { addToStock } from '../config/api';

export default function AddButton({ item, onAdd }) {
    async function onSelect() {
        try {
            await addToStock(item.foodName)

            toast(item.foodName + " has been added")
            if (onAdd) {
                onAdd(item.foodName)
            }
        } catch (error) {

            toast("There has been an error " + error + " with " + item.foodName + " please try again!")
        }
    }

    return (
        <button
            className="bg-teal-600 w-full text-white font-bold px-4 py-2 rounded"
            onClick={onSelect}>Add
        </button>
    )
}
